<?php $title = 'Minha conta'; ?><section class="container page-head"><p class="eyebrow">Área do anunciante</p><h1>Minha conta</h1><a class="button" href="<?= Helper::e(Helper::url('anunciar')) ?>">Novo anúncio</a></section><section class="container section"><h2>Meus anúncios</h2><?php if (!$properties): ?><div class="empty">Você ainda não cadastrou imóveis.</div><?php else: ?><div class="property-grid"><?php foreach ($properties as $property): ?><article class="property-card"><div class="property-body"><span class="tag <?= Helper::e($property['status']) ?>"><?= Helper::e(ucfirst($property['status'])) ?></span><h3><?= Helper::e($property['titulo']) ?></h3><p class="muted"><?= Helper::e($property['cidade']) ?> · <?= (int) $property['visualizacoes'] ?> visualizações</p></div></article><?php endforeach; ?></div><?php endif; ?></section>